"""Author Level 1 Week 3 as a connected lesson; keep source block positions."""
from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1];p=R/'content/programme.json';d=json.loads(p.read_text());w=next(x for x in d['weeks'] if x['id']=='ai-1/3')
if w['sections'][0].get('reading_flow'):raise SystemExit('Week 3 already authored; edit its metadata directly.')
original=copy.deepcopy(w)
def add(role,n,text=None,image=None,label=None):
 b=copy.deepcopy(image) if image else {'type':'paragraph','text':text,'presentation':{'kind':'body','paragraphs':[text],'emphasis':[]}}
 if label:b.setdefault('presentation',{})['label']=label
 b['reading_addition']='week3-connected-reading';w[role][n-1]['blocks'].append(b);return len(w[role][n-1]['blocks'])-1
def pic(n):return next(b for b in w['sections'][17]['blocks'] if b.get('src','').endswith(f'academy-story-ai-1-3-{n:02}'))
def g(title,indices,kind='text',collapsed=False,note=None):return {'title':title,'kind':kind,'indices':indices,**({'collapsed':True} if collapsed else {}),**({'note':note} if note else {})}
def design(role,n,title,purpose,groups,optional=False):
 s=w[role][n-1];used=[i for z in groups for i in z['indices']];assert len(used)==len(set(used)),(role,n)
 rest=[i for i in range(len(s['blocks'])) if i not in used]
 if rest:groups.append(g('Earlier wording, alternative practice and picture transcripts',rest,'reference',True))
 s['reading_flow']={'title':title,'purpose':purpose,'optional':optional,'groups':groups};s['reading_intro']=purpose
 assert sorted(i for z in groups for i in z['indices'])==list(range(len(s['blocks'])))

start=add('sections',1,'Two devices show different numbers. Before choosing which one to trust, ask: what was measured, in which units, where and when? This week you will separate a reading, a rule and a claim about the world.')
design('sections',1,'What does a sensor reading really tell us?','Describe a measurement, trace how it is used and compare devices fairly.',[g('Start with a disagreement',[start],'example'),g('Reconnect with information loss',[13,5,7]),g('By the end, you can…',[1,2,3],'prompts')])
design('sections',2,'The display says 24. Twenty-four what?','A number needs a quantity, unit and conditions before it becomes useful evidence.',[g('Read the garden display',[13],'example'),g('Complete the measurement record',[14]),g('A temperature is not a watering decision',[15],'example'),g('Notice before explaining',[6,9],'prompts')])
design('sections',3,'Measurement → rule → human decision','Follow three different jobs instead of treating the sensor as a gardener.',[g('Trace the garden system',[13]),g('Explain what the sensor changes',[14,10]),g('Read the boundary carefully',[15],'example'),g('Explain one arrow',[18],'prompts')])
gallery={'type':'gallery','layout':'reading-cards','reading_addition':'week3-connected-reading','cells':[[copy.deepcopy(w['sections'][3]['blocks'][3+i]),copy.deepcopy(w['sections'][3]['blocks'][7+i])] for i in range(4)]};w['sections'][3]['blocks'].append(gallery);idx=len(w['sections'][3]['blocks'])-1
design('sections',4,'Match the physical signal to its record','Use each picture’s evidence to distinguish sensing from interpretation.',[g('Four pictures with their explanations',[idx],'cards'),g('Discuss what could be confused',[12],'prompts'),g('Do not give the sensor an extra power',[11],'example')])
design('sections',5,'Your measurement word guide','Use the words to explain a particular reading or comparison.',[g('Core sensor words',[7]),g('Useful measurement terms',[13]),g('Repair a claim',[9,10],'prompts')],True)
comparison=add('sections',6,image=pic(3));trace=add('sections',6,image=pic(2));change=add('sections',6,image=pic(4))
predict=add('sections',6,'Before checking: move only B into brighter light. Can the earlier gap of 5 tell you its exact new reading? Explain which comparison condition changed and what information is missing.')
design('sections',6,'A repeated gap does not choose the accurate device','Compare the same quantity at matching times and locations, then limit your claim.',[g('Given facts: two fictional light sensors',[19,21,22],'example'),g('Read the paired measurements',[comparison]),g('Follow the fair comparison',[trace]),g('What the repeated gap supports',[27]),g('Predict after moving only B',[predict],'prompts'),g('Check the changed comparison',[change],'example',True),g('What three pairs cannot establish',[29],'example'),g('Explain the missing information',[30],'prompts')])
design('sections',7,'Repair a conclusion that outruns its evidence','A threshold warning does not diagnose everything about a plant.',[g('Find the unsupported step',[11],'example'),g('Keep the comparison ordinary and safe',[12]),g('Repair the two claims',[5,7,9,13],'prompts')])
boundary=add('sections',8,'Your W2 rule: turn a warning on when recorded temperature is greater than 28 degrees C. Predict the warning for 27, 28 and 29. Explain why a correctly applied rule does not by itself establish an accurate measurement.')
design('sections',8,'Practise: hold the right conditions steady','Separate a change in location from a difference between devices.',[g('Sunny window versus shade',[11,12],'example'),g('Trace the boundary yourself',[boundary,15,16,13],'steps'),g('Explain, check and switch',[17]),g('Does stability prove accuracy?',[19,20],'prompts'),g('Return to the changed light reading',[22,23,24])])
lab=add('sections',9,'Use fictional cards instead of recording people: (A) a pattern of light on a camera’s detector; (B) changing air pressure at a microphone; (C) the temperature at a thermometer. Match each to a picture record, sound record or temperature record. Keep the physical signal, the recorded data and a later interpretation in three separate columns.')
lab2=add('sections',9,'Before checking, predict which sensor fits “the room is happy”. The correct boundary is that no card directly measures happiness. For a missing-data case, mark a covered or disconnected sensor’s record as unavailable; do not invent a reading. Swap cards and explain your reasoning to a partner.')
design('sections',9,'Investigate: signal, record or interpretation?','Use supplied fictional cards to make the sensing boundary visible.',[g('Your three case cards',[lab],'example'),g('Predict, match and explain',[lab2,6,7,8],'steps'),g('Keep the trace and its limit',[9,12])])
design('sections',10,'Choose a stronger thinking challenge','Pick one next step that improves your explanation.',[g('Choose your challenge',list(range(4,11)),'prompts')],True)
design('sections',11,'Choose whether your sorter needs a sensor','A direct human entry may serve the classroom need better than adding a device.',[g('This week’s project decision',[4,14],'example'),g('Plan the data and human review',[5,6,7,8,9],'prompts'),g('Keep the sensing boundary clear',[11])])
design('sections',12,'Reference: check a measurement explanation','Use after practice. The sound-display comparison is this week’s selected independent case.',[g('Check your explanation',[5,6,7,8,9],'prompts'),g('Record support',[12])],True)
design('sections',13,'Extra practice: light, sound and feelings','Try the sensor question before opening the explanation.',[g('Read the case and question',[3,5],'example'),g('Your explanation',[9,10],'prompts'),g('Check after trying',[7,13],'example',True)],True)
design('sections',14,'Try alone: investigate the sound-display disagreement','Design a fair comparison and explain what two different results would mean.',[g('The new case',[1,2],'example'),g('Keep one first attempt',[3,17]),g('Use feedback afterwards',[22])])
design('sections',15,'Reference: original lesson checklist','Use an extra checklist when it helps you inspect your work.',[g('Targets and evidence',[1]),g('Keep the prediction and route',[2,3])],True)
design('sections',16,'Finish: give a measurement, then limit the claim','Close your notes and explain what a reading supports and what it does not.',[g('Your exit explanation',[0,1],'prompts'),g('Choose support and a later return',[2,3])])
for role,n in [('sections',17),('workbook',20)]:
 design(role,n,'Extra practice: sensor pictures and feedback','Try each question before opening its explanation. Use one paper or browser copy.',[g('First supported question',list(range(1,10)),'prompts'),g('Check the first explanation',[10],'example',True),g('Changed-condition question',list(range(11,18)),'prompts'),g('Check the changed condition',[18],'example',True),g('Repair and save',[20,22]+([23] if role=='workbook' else []))],True)
design('sections',18,'Reference: six-picture sensor journey','Use the image that helps your current question; the main comparison already appears in the lesson.',[g(w['sections'][17]['blocks'][4*i]['text'],list(range(4*i+1,4*i+4))) for i in range(6)],True)

design('teacher',1,'Prepare the sensor lesson','Teach the difference between a physical quantity, a recorded value and an interpretation.',[g('Learning goal and preparation',[1,19,26]),g('What to prepare',[16,22,23,24],'prompts'),g('Main teaching plan',[2,3]),g('Retrieve information loss',[6,7,8,21],'example')])
tpic=add('teacher',2,image=pic(3));ttrace=add('teacher',2,image=pic(2))
design('teacher',2,'Teach measurement before interpretation','Tie every conclusion to the quantity, recorded value, conditions and comparison evidence.',[g('Begin with the number 24',[20,21,22],'example'),g('Separate sensing, rule and decision',[23,24,4]),g('Model the light-sensor comparison',[36,38,39,tpic,ttrace,44],'example'),g('Move only one sensor',[48,49,50],'steps'),g('Limit the conclusion',[46]),g('Extend to temperature devices',[29,30,31,32],'example'),g('Use the visual deliberately',[34,52])])
design('teacher',3,'Guide the boundary and comparison reasoning','Listen for the deciding evidence rather than a correct warning label alone.',[g('Prompt before showing the key',[16],'example'),g('Expected trace and fading help',[17,18]),g('Check stability versus accuracy',[20,21,22],'example'),g('Use the changed light comparison',[24,26,27,28]),g('Keep each learner explaining',[7,8,10],'prompts')])
tlab=add('teacher',4,'Use the student lesson’s fictional camera, microphone and thermometer cards. Expected matches: light pattern → camera picture record; changing air pressure → microphone sound record; temperature → thermometer record. No sensor card directly measures happiness. A missing record stays unavailable. This is a paper classification exercise, not a personal-data collection task. Reserve the sound-display disagreement for the individual first attempt.')
design('teacher',4,'Run the signal-messenger investigation','Give fully specified fictional cards and keep readings separate from interpretations.',[g('Supplied cards and expected boundary',[tlab],'example'),g('Run the investigation',[3,4,5,6],'steps'),g('Keep an inspectable record',[10]),g('Diagnose the first misconception',[15,16,17],'cards'),g('Choose support from the response',[19,20])])
design('teacher',5,'Assess the sound-display investigation','Use the selected key after the first attempt; accept defensible comparisons and limits.',[g('Selected independent question and key',[31,33],'example'),g('Judge explanation, trace and limits',[34,35]),g('Give feedback that changes a step',[37]),g('W1: incomplete measurement record',[16,17],'example'),g('W2: warning boundary',[19,20],'example'),g('W3: paired differences',[22,23],'example'),g('W5: unsupported watering claim',[28,29],'example')])
design('teacher',6,'Connect, adapt and return','Retain the measurement context and revisit the reasoning with a changed case.',[g('Project evidence to keep',[2,3,20]),g('Remove barriers; retain the reasoning',[5,11,12]),g('Plan the delayed check',[15,16,17,18]),g('Connect to rules and learned patterns',[7,9,13])])
design('teacher',7,'Reference: alternative planning checklist','Use this as a reminder rather than teaching the same cycle twice.',[g('Preparation and schedule',[0,1,2]),g('Practice and assessment reminders',list(range(3,13)))],True)
design('teacher',8,'Reference: feedback and records','Use tools to keep an explanation and its evidence; the paper lesson needs no coding account.',[g('Keep practice separate from assessment',[0,1]),g('Repair and portfolio records',[3,4])],True)
design('teacher',9,'Reference: teach with the six pictures','Choose the picture for the teaching move, then connect it to a sentence.',[g(w['teacher'][8]['blocks'][1+5*i]['text'],list(range(2+5*i,6+5*i))) for i in range(6)],True)
main=[(1,'Recall · What did the summary lose?','Retrieve Week 2 before opening notes.'),(12,'W1 · Repair an incomplete record','Name missing fields without inventing observations.'),(13,'W2 · Trace the warning boundary','Apply greater than 28 carefully, then separate the rule from measurement quality.'),(14,'W3 · Compare without choosing a winner','Calculate paired differences and explain what a reference would add.'),(16,'W5 · Limit the watering conclusion','Distinguish a temperature warning from evidence about roots and watering.'),(4,'W4 · Investigate a new measurement dispute','Make one first attempt on the sound-display case before feedback.'),(9,'Project · Choose the measurement you need','Name a sensor only when it serves the sorter’s real task.'),(17,'Feedback · Repair and revisit','Keep the first attempt, its repair and a later changed-case check.'),(10,'Finish · Check what your evidence shows','Use work you can point to when judging independence.')]
for n,title,purpose in main:
 groups=([g('Retrieve and explain',[0,2,3],'prompts')] if n==1 else [g('Read and explain independently',[1,2],'example'),g('Keep a fair record',[3])] if n==4 else [g('Your project map',[0,1,2],'prompts')] if n==9 else [g('Your evidence record',[0,1])])
 design('workbook',n,title,purpose,groups)
refs={2:('Reference · Boundary practice copy','This is the same W2 attempt. Use one response record.'),3:('Extra practice · Does stability prove accuracy?','Explain which evidence would support closeness to a reference.'),5:('Reference · The light-sensor target','Use the target to check what the original unknown units permit.'),6:('Extra practice · Light and sound','Try before checking the worked explanation.'),7:('Extra practice · Readings and comfort','Keep this practice distinct from the reserved independent case.'),8:('Extra practice · Design a comparison','State a prediction before tracing or testing.'),11:('Reference · Light-comparison response','This teaching case is practice, not a fresh assessment.'),15:('Reference · Sound-display response copy','This duplicates W4. Reuse its first-attempt record.'),18:('Extra practice · Paired light readings','Use the picture and name the support you needed.'),19:('Reference · Sorter portfolio record','Extend your main project record if needed.'),21:('Reference · Six-picture response sheets','Choose a useful image; completing all six again is optional.')}
for n,(title,purpose) in refs.items():
 s=w['workbook'][n-1];groups=([g(s['blocks'][5*i]['text'],list(range(5*i+1,5*i+5))) for i in range(6)] if n==21 else [g('Use this when helpful',list(range(len(s['blocks']))))]);design('workbook',n,title,purpose,groups,True)
overviews={
 'sections':('Read the measurement. Limit the claim.','Start with an unexplained 24, trace the garden warning, compare paired light readings, then investigate a new disagreement.','Name the quantity and conditions → compare fairly → say what is still unknown.',[1,2,3,4,6,7,8,9,14,11,16,5,10,12,13,15,17,18],[('Notice',2),('Trace',3),('Compare',6),('Practise',8),('Try alone',14),('Build & reflect',11)]),
 'teacher':('Teach sensing as a limited evidence path.','Model the measurement record, distinguish sensing from decisions, compare devices fairly and reserve the sound-display case for independent evidence.','Look for recorded conditions, a fair comparison and a defensible limit.',list(range(1,10)),[('Prepare',1),('Explain',2),('Guide',3),('Investigate',4),('Assess',5),('Return',6)]),
 'workbook':('One connected measurement record.','Repair a record, trace a boundary, compare pairs, limit a conclusion and plan the reserved new investigation.','Keep the original reading, the conditions and the reason for your conclusion.',[1,12,13,14,16,4,9,17,10,2,3,5,6,7,8,11,15,18,19,20,21],[('Recall',1),('Record',12),('Trace',13),('Compare',14),('Limit',16),('Try alone',4)])}
for role,(title,lead,outcome,order,route) in overviews.items():
 w[role][0]['reading_flow']['overview']={'title':title,'lead':lead,'outcome':outcome,'order':order,'route':[{'label':label,'section':n} for label,n in route]}
 for before,after in zip(original[role],w[role]):assert before['blocks']==after['blocks'][:len(before['blocks'])]
# Resolve conflicting source labels; record each exact replacement.
changes=[]
def fix(role,n,i,text):
 b=w[role][n-1]['blocks'][i];old=b['text'];b['text']=text
 if b.get('presentation',{}).get('paragraphs'):b['presentation']['paragraphs']=[text]
 changes.append({'week':w['id'],'path':f'/{role}/{n-1}/blocks/{i}/text','old':old,'new':text})
fix('teacher',4,9,'Use the supplied sensor cards for shared practice. Each pair predicts a match and explains a missing-data case before checking. Reserve the sound-display disagreement for the individual first attempt; keep predicted and actual paper-trace results separate.')
fix('teacher',3,5,'Keep the light-and-temperature comfort question for optional later practice. Reserve the sound-display disagreement for the first independent attempt before feedback.')
fix('teacher',5,3,'Additional transfer practice: readings and comfort')
fix('teacher',5,5,'Reasoned comfort-practice answer')
fix('workbook',7,1,'My practice answer and reason')
fix('sections',12,1,'Checklist for a measurement explanation')
fix('sections',12,2,'Use this checklist after practice. The sound-display disagreement is this week’s selected independent case.')
fix('sections',12,4,'EXPLANATION CHECK  Name the quantity and units, trace how the recorded value is used, and explain a fair comparison and its limits.')
p.write_text(json.dumps(d,ensure_ascii=False,indent=2));lp=R/'reports/reviewed-source-corrections.json';l=json.loads(lp.read_text());l['corrections'].extend(changes);lp.write_text(json.dumps(l,ensure_ascii=False,indent=2)+'\n')
(R/'reports/week3-connected-reading.json').write_text(json.dumps({'lesson':w['id'],'sections_reviewed':48,'original_blocks_preserved':True,'wording_corrections':changes,'roles':{role:{'main_sections':sum(not s['reading_flow']['optional'] for s in w[role]),'reference_sections':sum(s['reading_flow']['optional'] for s in w[role]),'sections':[{'title':s['reading_flow']['title'],'groups':[g['title'] for g in s['reading_flow']['groups']]} for s in w[role]]} for role in overviews}},indent=2)+'\n')
print('Authored all 48 Week 3 sections; original block positions retained.')
